def top_k_frequent(nums, k):
    if not nums or k <= 0:
        return []
    freq = {}
    order = []
    for n in nums:
        if n not in freq:
            freq[n] = 0
            order.append(n)
        freq[n] += 1
    sorted_items = sorted(order, key=lambda x: -freq[x])
    return sorted_items[:k]

